nta.declaration:
/** * Redlock F9（時鐘突跳 / NTP Step）—— UPPAAL 時間自動機模型 * * 目的：回答一個 Quint 模型回答不了的問題——「客戶端與節點的物理時鐘不同步」 * 是否足以獨立破壞 Redlock 的互斥性？ * * --------------------------------------------------------------------------- * 建模關鍵一：UPPAAL 的 clock 不能被位移 * * UPPAAL 的 clock 只能「重設為 0」，**不能被讀進算術式**。 * 寫成 `c_node[1] := c_node[1] + DELTA` 會被型別檢查擋下： * [error] When using symbolic methods clock cannot be read as double value * 這是 DBM（Difference Bound Matrix）zone 抽象的固有限制，不是語法糖問題。 * * 因此所有時鐘突跳一律以**整數偏移量**表達，把位移搬進 guard 的常數側： * 節點的有效經過時間 = c_node[i] + node_ofs[i] * → TTL 判斷 `c_node[i] >= DURATION - node_ofs[i]` * 客戶端量到的經過時間 = c_client[c] - client_skew[c] * → 租約判斷 `c_client[c] < DURATION - DRIFT + client_skew[c]` * * --------------------------------------------------------------------------- * 建模關鍵二：兩種時鐘異常必須分開，否則 F9 與 F8 無法區分 * * NodeClockAdversary —— 節點時鐘**往前**跳：key 比客戶端預期更早過期。 * 這在效果上等同於「節點崩潰遺失 key」（F8 / Kleppmann）， * Quint 模型已用 crashAndLoseKey 證過。 * * ClientClockAdversary —— 客戶端時鐘**往後**跳：客戶端高估自己的剩餘租約， * 賴在臨界區超過真實 TTL。**這才是 F9 的本體**： * 它不需要任何節點異常就能破壞互斥性。 * * 兩者各自有計數器（node_jumps / client_jumps），因此「陰性對照」與 * 「F9 與 F8 的分離」都可以直接寫成**查詢條件**，不必修改模型檔案： * E<> (兩者同時在臨界區 && node_jumps == 0 && client_jumps == 0) 應為 NOT satisfied * E<> (兩者同時在臨界區 && node_jumps == 0) 應為 SATISFIED ← F9 * --------------------------------------------------------------------------- */
// --- 系統規模 --- const int N = 3; // Redis 節點數（0, 1, 2） const int M = 2; // 並行客戶端數（0, 1） const int QUORUM = 2; // floor(N/2) + 1
// --- 時間參數（毫秒）--- const int DURATION = 20; // 鎖的 TTL const int DRIFT = 2; // driftFactor 補償量；客戶端相信的租約 = DURATION - DRIFT const int MIN_NET_DELAY = 1; // 單次請求的最小網路延遲 const int MAX_NET_DELAY = 3; // 單次請求的最大網路延遲
// --- 對手能力上界（同時也是狀態空間的控制旋鈕）--- const int MAX_STEP = 15; // 單次時鐘突跳的最大幅度（非確定性選取 1..MAX_STEP） const int MAX_JUMPS = 1; // 每一種對手最多能發動幾次突跳
typedef int[0, N - 1] node_id_t; typedef int[0, M - 1] client_id_t;
// --- 連續時鐘：每個節點、每個客戶端各自獨立 --- clock c_node[N]; clock c_client[M];
// --- 時鐘突跳的整數編碼（見檔頭「建模關鍵一」）--- int[0, MAX_STEP * MAX_JUMPS] node_ofs[N]; // 節點時鐘往前跳的累積量 int[0, MAX_STEP * MAX_JUMPS] client_skew[M]; // 客戶端時鐘往後跳的累積量
// --- 突跳計數器：讓陰性對照與 F9/F8 分離可以寫成查詢條件 --- int[0, MAX_JUMPS] node_jumps = 0; int[0, MAX_JUMPS] client_jumps = 0;
// --- 節點狀態：-1 表示無人持有 --- int[-1, M - 1] lock_holder[N] = {-1, -1, -1};
// --- 客戶端與節點之間的同步通道 --- chan req_grant[M][N]; chan req_reject[M][N]; chan unlock[M][N];

nta.system:
// 具現化
Node0 = RedisNode(0);
Node1 = RedisNode(1);
Node2 = RedisNode(2);

Client0 = Client(0);
Client1 = Client(1);

NodeAdv   = NodeClockAdversary();
ClientAdv = ClientClockAdversary();

system Node0, Node1, Node2, Client0, Client1, NodeAdv, ClientAdv;
